import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.C92HYyu1.js";var i=JSON.parse(`{"title":"System Architecture & Clean Architecture | SyncCMS","description":"Overview of SyncCMS Clean Architecture 4-layer structure with Spring Boot 3, LangChain4j, and Vue 3.","frontmatter":{"title":"System Architecture & Clean Architecture | SyncCMS","description":"Overview of SyncCMS Clean Architecture 4-layer structure with Spring Boot 3, LangChain4j, and Vue 3.","sort":2,"head":[["link",{"rel":"canonical","href":"https://empasy.io/docs/en/synccms/architecture.html"}]]},"headers":[],"relativePath":"en/synccms/architecture.md","filePath":"en/synccms/architecture.md","lastUpdated":1787437905000}`),a={name:`en/synccms/architecture.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="synccms-system-architecture" tabindex="-1">SyncCMS System Architecture <a class="header-anchor" href="#synccms-system-architecture" aria-label="Permalink to “SyncCMS System Architecture”">​</a></h1><p>SyncCMS is designed on a <strong>4-Layer Clean Architecture</strong> to guarantee high scalability, security, and developer freedom in high-traffic enterprise environments.</p><ul><li><strong>Presentation Layer</strong>: Hybrid Headless REST API + Sync-Live-SDK for React, Vue, Next.js, iOS, Android.</li><li><strong>Security Layer</strong>: Stateless JWT auth, granular multi-tier RBAC, audit logging for financial compliance.</li><li><strong>Core Layer</strong>: Java Spring Boot 3 standard framework, LangChain4j AI orchestration engine, snapshot rollback engine.</li><li><strong>Data &amp; Infra Layer</strong>: Open schema DB (Oracle, PostgreSQL, MySQL), PGVector RAG store, on-premise private LLMs (vLLM / Ollama).</li></ul>`,3)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};